        public static string T(string es)
        {
            if (string.IsNullOrEmpty(es) || _lang == "es") return es;
            if (_lang != "en") { var o = Other; if (o != null && o.TryGetValue(es, out var t)) return t; }
            return En.TryGetValue(es, out var v) ? v : es;
        }
